#include <bits/stdc++.h>
using namespace std;
int main(){for(auto [m,n]:vector<pair<int,int>>{{3,3},{3,4},{3,5},{3,6},{4,4},{4,5}}){int N=m*n;vector<unsigned long long> closed(N); vector<pair<int,int>> edges;for(int i=0;i<N;i++){int r=i/n,c=i%n;for(int j=0;j<N;j++)if(j/n==r||j%n==c)closed[i]|=1ULL<<j;for(int j=i+1;j<N;j++)if(j/n==r||j%n==c)edges.push_back({i,j});}long long bestCnt=0, valid=0;int best=N+1;for(unsigned long long C=1;C<(1ULL<<N);++C){ bool ok=true;for(auto ne:closed)if((C&ne)==0){ok=false;break;}if(!ok)continue;for(auto [i,j]:edges){if((C & (closed[i]^closed[j]))==0){ok=false;break;}}if(!ok)continue;valid++;int k=__builtin_popcountll(C);if(k<best){best=k;bestCnt=0;}if(k==best)bestCnt++;} cout<<m<<" "<<n<<" min="<<best<<" opt="<<bestCnt<<" total="<<valid<<"\n";}}
